from threetears.evals import Eval

from naming import stored_name


def file_it(case):
    """The name the new store files the document under."""
    return {"name": stored_name(case["title"], case["uploaded"], case["extension"])}


def keeps_archive_name(case, out):
    """The document keeps the name the archive gave it."""
    return out["name"] == case["archive_name"]


archive = Eval("data/archive_index.jsonl", runner=file_it, grader=[keeps_archive_name], k=1)
